var list_menu_default = defineTool({
  name: "list_menu",
  title: "Listar card\xE1pio",
  description: "Lista os produtos ativos do card\xE1pio da UP Esfihas Artesanais (nome, categoria, descri\xE7\xE3o e pre\xE7o). Opcionalmente filtra por categoria ou por texto de busca.",
  inputSchema: {
    categoria: z.string().optional().describe("Filtra por categoria exata, ex: 'Esfihas Salgadas'."),
    busca: z.string().optional().describe("Texto para buscar no nome do produto.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ categoria, busca }, ctx) => {
    if (!ctx.isAuthenticated()) return errorResult("N\xE3o autenticado.");
    let query = supabaseForUser(ctx).from("produtos").select("id, nome, categoria, descricao, preco").eq("ativo", true).order("categoria").order("nome");
    if (categoria) query = query.eq("categoria", categoria);
    if (busca) query = query.ilike("nome", `%${busca}%`);
    const { data, error } = await query;
    if (error) return errorResult(error.message);
    return textResult({ total: data?.length ?? 0, produtos: data ?? [] });
  }
});

