import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.25.76";
var list_my_orders_default = defineTool4({
  name: "list_my_orders",
  title: "Meus pedidos",
  description: "Lista os pedidos do usu\xE1rio autenticado, do mais recente para o mais antigo, com n\xFAmero, status, total, forma de pagamento e itens.",
  inputSchema: {
    limite: z2.number().int().optional().describe("Quantidade m\xE1xima de pedidos a retornar (padr\xE3o 10)."),
    status: z2.string().optional().describe("Filtra por status: pendente, aceito, preparo, saiu_entrega, finalizado, cancelado, aguardando_pagamento.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ limite, status }, ctx) => {
    if (!ctx.isAuthenticated()) return errorResult("N\xE3o autenticado.");
    const max = Math.min(Math.max(limite ?? 10, 1), 50);
    let query = supabaseForUser(ctx).from("pedidos").select(
      "id, numero, status, total, subtotal, taxa_entrega, metodo_pagamento, troco, observacao_pagamento, items, endereco, created_at"
    ).eq("user_id", ctx.getUserId()).order("created_at", { ascending: false }).limit(max);
    if (status) query = query.eq("status", status);
    const { data, error } = await query;
    if (error) return errorResult(error.message);
    return textResult({ total: data?.length ?? 0, pedidos: data ?? [] });
  }
});

